// A synthetic trade tape: 3 made-up symbols, 4 traders, one trading day from 09:00.
function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(30);
const price = { ACME: 50, BOLT: 120, CRUX: 8.5 };   // starting prices
const symbols = Object.keys(price), traders = ['T1', 'T2', 'T3', 'T4'];
const clock = s => {
  const t = 9 * 3600 + s;
  return [Math.floor(t / 3600), Math.floor(t / 60) % 60, t % 60].map(x => String(x).padStart(2, '0')).join(':');
};

const trades = [];
let ts = 0;
for (let id = 1; id <= 3000; id++) {
  ts += 1 + Math.floor(rand() * 18);                 // about one trade every 9.5 seconds
  const symbol = symbols[Math.floor(rand() * symbols.length)];
  price[symbol] *= 1 + (rand() - 0.5) * 0.002;       // a small random walk
  trades.push({
    trade_id: id, ts, time: clock(ts), symbol,
    trader: traders[Math.floor(rand() * traders.length)],
    side: rand() < 0.5 ? 'BUY' : 'SELL',
    qty: 100 * (1 + Math.floor(rand() * 20)),
    price: Math.round(price[symbol] * 10000) / 10000,
  });
}
nb.set('trades', trades);
console.log(trades.length + ' trades from ' + trades[0].time + ' to ' + trades.at(-1).time);
console.log('first trade: ' + JSON.stringify(trades[0]));
const per = symbols.map(s => s + ' ' + trades.filter(t => t.symbol === s).length);
console.log('trades per symbol: ' + per.join(', '));

// Recompute the SQL answers in plain JavaScript, then chart the positions.
const trades = nb.get('trades'), positions = nb.get('positions'), volume = nb.get('volume5');
if (!trades || !positions || !volume) return 'Run the cells above first.';

// 1. Running positions: walk the trades in time order, keeping a total per trader and symbol.
const ordered = [...trades].sort((a, b) => a.ts - b.ts || a.trade_id - b.trade_id);
const running = {}, mine = {};
for (const t of ordered) {
  const key = t.trader + ' ' + t.symbol;
  running[key] = (running[key] || 0) + (t.side === 'BUY' ? t.qty : -t.qty);
  mine[t.trade_id] = running[key];
}
const posMismatch = positions.filter(p => p.position !== mine[p.trade_id]).length;
console.log('running positions: ' + positions.length + ' rows checked, ' + posMismatch + ' differ');

// 2. Rolling 5-minute volume: for each saved row, add up that symbol's trades in [ts - 299, ts].
const volMismatch = volume.filter(v => {
  const sum = trades.filter(t => t.symbol === v.symbol && t.ts >= v.ts - 299 && t.ts <= v.ts)
    .reduce((s, t) => s + t.qty, 0);
  return sum !== v.volume_5min;
}).length;
console.log('rolling 5-minute volume: ' + volume.length + ' rows checked, ' + volMismatch + ' differ');
const top = volume[0];
console.log('busiest 5 minutes: ' + top.symbol + ' up to ' + top.time + ', ' + top.volume_5min + ' shares in ' + top.trades_5min + ' trades');

const closing = Object.entries(running).map(([k, v]) => k + ' ' + v).join(', ');
console.log('closing positions: ' + closing);

const acme = positions.filter(p => p.symbol === 'ACME').map(p => ({ hour: 9 + p.ts / 3600, position: p.position, trader: p.trader }));
return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 260,
  title: 'Each trader\'s position in ACME through the day',
  data: { values: acme },
  mark: { type: 'line', interpolate: 'step-after', strokeWidth: 1.8 },
  encoding: {
    x: { field: 'hour', type: 'quantitative', title: 'time of day (hours)', scale: { domain: [9, 17] } },
    y: { field: 'position', type: 'quantitative', title: 'shares held (negative = short)' },
    color: { field: 'trader', type: 'nominal', title: null },
  },
};
